// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address newOwner) public {
        // As the current owner (this contract's initial caller), attempt ownership transfer
        // We use vm.prank to ensure the call is made by the owner (msg.sender == address(this) during setUp)
        // However, setUp runs with msg.sender = this contract, so c.owner() will be this contract initially.
        // To be explicit, we prank as the current owner.
        address currentOwner = c.owner();
        vm.assume(newOwner != currentOwner); // ensure a change is attempted, fuzzer still has wide space
        vm.prank(currentOwner);
        bool success;
        try c.transferOwnership(newOwner) { success = true; } catch { success = false; }
        // Reference C: success should be true, and c.owner() should be newOwner.
        // Buggy C: success is false (revert), and c.owner() remains currentOwner.
        // Universal rule: If transferOwnership succeeds, owner must have changed;
        // If it fails, owner must remain unchanged.
        // We assert that the call did not revert AND the owner changed.
        // This holds for ALL inputs in ref, violated by SOME input in bug (any newOwner != currentOwner).
        assertTrue(success && c.owner() == newOwner);
    }
}

