contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller, address fuzzOwner) public {
        // Restrict to admissible domain: caller may or may not be the owner
        vm.assume(fuzzOwner != address(0));
        vm.assume(fuzzOwner != caller); // ensure more likely non-owner scenarios are covered
        // Set owner to a fuzzed address
        vm.prank(c.owner());
        c.transferOwnership(fuzzOwner);
        // Record whether caller is the current owner
        bool isOwner = (caller == c.owner());
        // Attempt owned() as the fuzzed caller
        vm.prank(caller);
        bool ok;
        try c.owned() { ok = true; } catch { ok = false; }
        // Rule: owned() succeeds exactly when caller is the owner
        assertTrue(ok == isOwner);
    }
}

