pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address owner, address caller) public {
        vm.assume(owner != address(0));
        vm.assume(caller != address(0));
        vm.assume(owner != caller); // ensure caller is not the initial owner (address(0)) — no issue here
        // Set up: make the fuzzed 'owner' the actual owner
        vm.prank(address(0)); // initial owner is address(0)
        c.transferOwnership(owner);
        // Now call owned() as the fuzzed caller
        vm.prank(caller);
        bool ok;
        try c.owned() { ok = true; } catch { ok = false; }
        // Rule: owned() succeeds if and only if caller == owner
        // Both contracts: if caller == owner, it should succeed; otherwise revert.
        // Mutant always reverts, so for caller == owner, original succeeds but mutant fails.
        if (caller == owner) {
            assertTrue(ok);
        } else {
            assertTrue(!ok);
        }
    }
}

